<?php require_once __DIR__ . '/includes/init.php'; if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf(); $action=$_POST['action']??''; $vid=(int)($_POST['variant_id']??0); $cart=cart_items(); if($action==='remove')unset($cart[$vid]); if($action==='update'&&$vid>0)$cart[$vid]=max(1,min(10,(int)($_POST['quantity']??1))); $_SESSION['cart']=$cart; cart_persist(); redirect('cart.php');} $items=[]; $cart=cart_items(); if($cart){$ids=implode(',',array_map('intval',array_keys($cart))); $items=db_all("SELECT v.id variant_id,v.size,v.color,p.name,p.slug,p.price,p.sale_price FROM product_variants v JOIN products p ON p.id=v.product_id WHERE v.id IN ($ids)");} $total=0; foreach($items as &$item){$item['quantity']=(int)$cart[$item['variant_id']];$item['line']=$item['quantity']*effective_price($item);} unset($item); foreach($items as $item)$total+=$item['line']; $pageTitle='Shopping cart'; require __DIR__.'/includes/header.php'; ?><main class="container page-section"><p class="eyebrow">Your selection</p><h1>Shopping cart</h1><?php if(!$items): ?><div class="empty-state"><h3>Your cart is empty</h3><p>Add something from the BFM collection to get started.</p><a class="btn btn-primary" href="<?=e(url('shop.php'))?>">Continue shopping</a></div><?php else: ?><div class="cart-layout"><div class="cart-list"><?php foreach($items as $item): ?><article class="cart-row"><div><h2><?=e($item['name'])?></h2><p><?=e($item['color'])?> · <?=e($item['size'])?></p><strong><?=e(money($item['line']))?></strong></div><form method="post" class="cart-controls"><?=csrf_field()?><input type="hidden" name="variant_id" value="<?=$item['variant_id']?>"><input type="number" name="quantity" min="1" max="10" value="<?=$item['quantity']?>"><button class="btn btn-outline btn-sm" name="action" value="update">Update</button><button class="link-button" name="action" value="remove">Remove</button></form></article><?php endforeach; ?></div><aside class="cart-summary"><h2>Order summary</h2><p>Total <strong><?=e(money($total))?></strong></p><a class="btn btn-primary btn-block" href="<?=e(url(is_logged_in()?'checkout.php':'login.php?next=/checkout.php'))?>">Checkout</a></aside></div><?php endif; ?></main><?php require __DIR__.'/includes/footer.php'; ?>
